"""Load the cleaned headlines saved by Episode 1."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PROCESSED = ROOT / "data" / "processed"
HEADLINES = PROCESSED / "headlines.jsonl"
TOKENIZER = PROCESSED / "char_tokenizer.json"

# Decided after Episode 1: template families generated by machine, left out when training
# the toy GPT. Analyst ratings stay: templated, but each one is a real event.
MACHINE_MADE_KINDS = (
    "trading_halt",
    "movers_roundup",
    "options_activity",
    "returns_calculator",
    "market_sentiment",
    "peer_comparison",
    "pe_ratio",
)


def load_headlines(split=None, exclude_kinds=()):
    """Return the cleaned headlines as a list of dicts, oldest first.

    split:          "train", "val", or None for both.
    exclude_kinds:  e.g. ("trading_halt", "movers_roundup") to drop boilerplate.
    """
    rows = []
    with HEADLINES.open(encoding="utf-8") as f:
        for line in f:
            row = json.loads(line)
            if split and row["split"] != split:
                continue
            if row["kind"] in exclude_kinds:
                continue
            rows.append(row)
    return rows


def as_text(rows):
    """Join headlines into one long string, one headline per line.

    The newline doubles as an "end of headline" marker the model can learn.
    """
    return "".join(row["headline"] + "\n" for row in rows)
